import {analyticsData,treemapLayout} from './analytics-model.mjs';
import {groups} from './model.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:d}).format(v);
const short=v=>v>=1e6?fmt(v/1e6,1)+'m':v>=1000?fmt(v/1000,1)+'k':fmt(v,2);
const colour=s=>`var(--color-scope${s})`;
function donut(d,filter,scale,unit){
 let offset=0;const circumference=2*Math.PI*75;
 return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 210 210" role="group" aria-label="Scope share. Select a segment to filter."><circle class="donut-track" cx="105" cy="105" r="75" fill="none" stroke-width="27"/>${d.fullScopes.map((v,i)=>{const length=d.fullTotal?v/d.fullTotal*circumference:0,start=offset;offset+=length;const tip=`Scope ${i+1}: ${fmt(v*scale,2)} ${unit} (${fmt(d.fullTotal?v/d.fullTotal*100:0,1)}% of entered inventory)`;return length?`<circle class="chart-point ${filter.scope&&filter.scope!==i+1?'dimmed':''}" role="button" tabindex="0" aria-pressed="${filter.scope===i+1}" aria-label="Filter Scope ${i+1}" data-chart-scope="${i+1}" data-tip="${esc(tip)}" cx="105" cy="105" r="75" fill="none" stroke="${colour(i+1)}" stroke-width="27" stroke-dasharray="${length} ${circumference-length}" stroke-dashoffset="${-start}" transform="rotate(-90 105 105)"><title>${esc(tip)}</title></circle>`:'';}).join('')}<text x="105" y="104" text-anchor="middle" class="donut-value">${short(d.fullTotal*scale)}</text><text x="105" y="125" text-anchor="middle" class="donut-unit">${unit}</text></svg><div class="donut-legend">${d.fullScopes.map((v,i)=>`<button class="legend-item ${filter.scope===i+1?'is-selected':''}" data-chart-scope="${i+1}" aria-pressed="${filter.scope===i+1}"><span class="dot s${i+1}"></span><span>Scope ${i+1}</span><strong>${fmt(v*scale,2)}</strong><small>${fmt(d.fullTotal?v/d.fullTotal*100:0,1)}%</small></button>`).join('')}</div></div>`;
}
function sourceBars(d,filter,scale,unit){const max=d.sources[0]?.value??0;return `<div class="analytic-bars">${d.sources.map(s=>`<button class="analytic-bar ${filter.group&&filter.group!==s.group?'dimmed':''} ${filter.group===s.group?'is-selected':''}" data-chart-group="${s.group}" aria-pressed="${filter.group===s.group}" data-tip="${esc(groups[s.group])}: ${fmt(s.value*scale,2)} ${unit}"><span class="analytic-bar-head"><span>${esc(groups[s.group]??s.group)}</span><strong>${fmt(s.value*scale,2)}</strong></span><span class="bar-track"><span class="bar-fill" style="width:${max?s.value/max*100:0}%;display:flex">${s.scopeValues.map((value,i)=>`<span style="width:${value/s.value*100}%;background:${colour(i+1)}"></span>`).join('')}</span></span></button>`).join('')}</div>`;}
function treemap(d,filter,scale,unit){const tiles=treemapLayout(d.sources.flatMap(s=>s.scopeValues.map((value,i)=>({...s,value,tileScope:i+1})).filter(s=>s.value>0)),700,290),sum=d.sources.reduce((s,n)=>s+n.value,0);return `<svg class="treemap" viewBox="0 0 700 290" role="group" aria-label="Source treemap. Rectangle area is proportional to emissions. Select a rectangle to filter.">${tiles.map(t=>{const name=groups[t.group]??t.group,label=t.width>140?name:t.width>95?name.split(' ')[0]:'';const tip=`Scope ${t.tileScope} · ${name}: ${fmt(t.value*scale,2)} ${unit} · ${fmt(t.value/sum*100,1)}% of current scope`;return `<g role="button" tabindex="0" aria-label="Filter ${esc(name)}" aria-pressed="${filter.group===t.group}" data-chart-group="${t.group}" data-tip="${esc(tip)}" class="chart-point tree-tile ${filter.group&&filter.group!==t.group?'dimmed':''} ${filter.group===t.group?'is-selected':''}"><title>${esc(tip)}</title><rect x="${t.x}" y="${t.y}" width="${t.width}" height="${t.height}" fill="${colour(t.tileScope)}"/>${label&&t.height>48?`<text x="${t.x+13}" y="${t.y+25}" class="tree-label">${esc(label)}</text>`:''}${t.width>78&&t.height>80?`<text x="${t.x+13}" y="${t.y+52}" class="tree-value">${short(t.value*scale)}</text><text x="${t.x+13}" y="${t.y+73}" class="tree-share">${fmt(t.value/sum*100,1)}% · ${unit}</text>`:''}</g>`;}).join('')}</svg>`;}
function waterfall(d,scale,unit){
 if(!d.calculated)return '<div class="empty">Enter activity data to build a reduction scenario.</div>';
 const columns=[{label:'Current',before:d.baseline,after:0,value:d.baseline,total:true},...d.waterfall.map(a=>({label:a.title,before:a.before,after:a.after,value:a.saving,total:false})),{label:'With actions',before:d.projected,after:0,value:d.projected,total:true}];
 const width=Math.max(650,columns.length*105),left=66,right=20,top=32,bottom=220,plot=width-left-right,step=plot/columns.length,bar=Math.min(70,step*.65),max=d.baseline||1,y=v=>bottom-v/max*(bottom-top);
 return `<div class="waterfall-scroll"><svg class="waterfall" viewBox="0 0 ${width} 295" style="min-width:${width}px" role="img" aria-label="Current emissions ${fmt(d.baseline*scale,2)} ${unit}, potential reduction ${fmt(d.avoided*scale,2)}, projected emissions ${fmt(d.projected*scale,2)}.">${[0,.25,.5,.75,1].map(f=>`<line x1="${left}" x2="${width-right}" y1="${y(max*f)}" y2="${y(max*f)}" class="chart-grid"/><text x="${left-10}" y="${y(max*f)+4}" text-anchor="end" class="axis-label">${short(max*f*scale)}</text>`).join('')}${columns.map((c,i)=>{const x=left+step*i+(step-bar)/2;const label=c.total?c.label:c.label.replace('Work with high-impact suppliers','Suppliers').replace('Use less electricity per batch','Electricity').replace('Reduce packaging material','Packaging').replace('Improve boiler & steam efficiency','Process energy').replace('Consolidate inbound deliveries','Freight').replace('Prevent refrigerant leakage','Refrigerants').replace('Prevent production waste','Waste');return `<g class="waterfall-point" tabindex="0" data-tip="${esc(c.label)}: ${c.total?'':'−'}${fmt(c.value*scale,2)} ${unit}"><title>${esc(c.label)}: ${c.total?'':'−'}${fmt(c.value*scale,2)} ${unit}</title><rect x="${x}" y="${y(c.before)}" width="${bar}" height="${Math.max(0,y(c.after)-y(c.before))}" rx="3" fill="${c.total?'var(--color-accent)':colour(3)}"/><text class="waterfall-value" x="${x+bar/2}" y="${Math.max(17,y(c.before)-9)}" text-anchor="middle">${c.total?'':'−'}${short(c.value*scale)}</text><text class="axis-label" x="${x+bar/2}" y="245" text-anchor="middle">${esc(label)}</text></g>${i<columns.length-1?`<line x1="${x+bar}" x2="${x+step}" y1="${y(i===0?c.before:c.after)}" y2="${y(i===0?c.before:c.after)}" class="waterfall-connector"/>`:''}`;}).join('')}<text x="${left}" y="278" class="axis-label">${unit} · sequential reductions, no double counting</text></svg></div>`;
}
export function renderAnalytics(state){
 const filter=state.analytics,d=analyticsData(state.rows,state.actions,filter),scale=filter.unit==='kg'?1000:1,unit=filter.unit==='kg'?'kg CO₂e':'t CO₂e';
 const selection=[filter.scope?'Scope '+filter.scope:'All scopes',filter.group?groups[filter.group]:'All sources'].join(' / ');
 const cards=[['Selected emissions',d.calculated?fmt(d.baseline*scale,2):'—',unit],['With selected actions',d.calculated?fmt(d.projected*scale,2):'—',unit],['Potential reduction',d.calculated?fmt(d.avoided*scale,2):'—',`${fmt(d.percent,1)}% of selected subtotal`]];
 return `<div class="page-head"><div><h1>Visual analytics</h1><p>${esc(state.company)} · FY ${state.year} · interactive screening inventory</p></div><div class="head-actions"><button class="btn" data-chart-reset>Reset filters</button><a class="btn primary" href="#activities">Edit data ↗</a></div></div><div class="demo-note"><span><strong>Illustrative or user-supplied inputs—not a verified Unilever inventory.</strong> Click a chart to filter. Missing activities and unassessed categories remain outside the totals.</span></div>
 <section class="panel analytics-toolbar" aria-label="Chart filters"><div class="filters" role="group" aria-label="Filter charts by scope">${[0,1,2,3].map(s=>`<button class="filter ${filter.scope===s?'selected':''}" data-chart-scope="${s}" aria-pressed="${filter.scope===s}">${s?'Scope '+s:'All scopes'}</button>`).join('')}</div><label class="unit-control">Display unit<select id="chart-unit" aria-label="Chart display unit"><option value="t" ${filter.unit==='t'?'selected':''}>Tonnes CO₂e</option><option value="kg" ${filter.unit==='kg'?'selected':''}>Kilograms CO₂e</option></select></label></section>
 <div class="selection-note" role="status"><span>${esc(selection)}</span><span>${d.calculated} calculated · ${d.missing} missing inputs${filter.group?' <button class="text-btn" data-chart-clear-source>Clear source ×</button>':''}</span></div><div class="analytics-kpis">${cards.map(([label,value,sub],i)=>`<section class="panel ${i===2?'savings-kpi':''}"><span class="eyebrow">${label}</span><strong>${value}</strong><small>${sub}</small></section>`).join('')}</div>
 <div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Emissions by scope</h2><p>Full entered inventory · click a scope to filter</p></div></div>${donut(d,filter,scale,unit)}<p class="panel-foot">Percentages describe calculated emissions only. A missing scope is not a zero-emission scope.</p></section><section class="panel"><div class="panel-head"><div><h2>Source ranking</h2><p>${filter.scope?'Scope '+filter.scope:'All scopes'} · click a source to filter</p></div><span class="muted">${unit}</span></div>${d.sources.length?sourceBars(d,filter,scale,unit):'<div class="empty">No positive calculated emissions in this scope.</div>'}</section>
 <section class="panel analytics-wide"><div class="panel-head"><div><h2>Emission hotspots</h2><p>Area represents emissions · colour represents scope · click to inspect</p></div><div class="chart-key">${[1,2,3].map(s=>`<span><i class="dot s${s}"></i>Scope ${s}</span>`).join('')}</div></div>${d.sources.length?treemap(d,filter,scale,unit):'<div class="empty">Add activity data to see the treemap.</div>'}<div class="tree-source-buttons">${d.sources.map(s=>`<button class="text-btn ${filter.group===s.group?'active-source':''}" data-chart-group="${s.group}" aria-pressed="${filter.group===s.group}">${esc(groups[s.group]??s.group)}</button>`).join('')}</div></section>
 <section class="panel analytics-wide"><div class="panel-head"><div><h2>From baseline to reduction</h2><p>Waterfall for ${esc(selection.toLowerCase())}</p></div><a href="#plan" class="text-btn">Adjust actions →</a></div>${waterfall(d,scale,unit)}<p class="panel-foot">Potential savings use the percentages selected in Reduction plan. They are scenario assumptions, not forecasts.</p></section></div>
 <section class="panel analytics-detail"><div class="panel-head"><div><h2>Data behind the selection</h2><p>${esc(selection)} · values shown to up to two decimal places</p></div><span class="muted">${d.selectedRows.length} rows</span></div><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Scope</th><th>Data status</th><th class="num">${unit}</th></tr></thead><tbody>${d.selectedRows.map(r=>`<tr><td>${esc(r.name)}</td><td><span class="dot s${r.scope}"></span>${r.scope}</td><td>${r.tonnes===null?'Missing inputs':r.quality==='illustrative'?'Illustrative':'User supplied'}</td><td class="num">${r.tonnes===null?'Unknown':fmt(r.tonnes*scale,2)}</td></tr>`).join('')}</tbody></table></div>${!d.selectedRows.length?'<div class="empty">No activity rows match these filters.</div>':''}</section><div class="chart-tooltip" id="chart-tooltip" role="tooltip" hidden></div>`;
}
